--IOWA LIBRARIES DATABASE
--Kristina Gavin Bigsby 
--Data collected from State Library of Iowa (https://www.statelibraryofiowa.gov/index.php/libraries/resources/directory) and Carnegie Libraries in Iowa Project (https://carnegielibrariesiowa.org/)

--DROP TABLES
DROP TABLE GRANTS;
DROP TABLE CITIES;
DROP TABLE LIBRARIES;
DROP TABLE DISTRICTS;

--CREATE TABLES
CREATE TABLE DISTRICTS (
    DistrictID CHAR(6) NOT NULL,
    District VARCHAR2(50) NOT NULL CHECK (District IN ('CE','NC','NE','NW','SE','SW')),
    Population NUMBER(*,0) NOT NULL CHECK (Population>=0),
    Area NUMBER(*,0) NOT NULL CHECK (Area>=0),
    CONSTRAINT DISTRICTS_PK PRIMARY KEY (DistrictID)
);

CREATE TABLE LIBRARIES (
    LibraryID CHAR(6) NOT NULL,
    Library VARCHAR2(200) NOT NULL,
    BranchOf CHAR(6),
    Address VARCHAR2(200) NOT NULL,
    City VARCHAR2(200) NOT NULL,
    Zip CHAR(5) NOT NULL,
    Phone CHAR(12) NOT NULL,
    Website VARCHAR2(200),
    DistrictID CHAR(6) NOT NULL,
    CONSTRAINT LIBRARIES_PK PRIMARY KEY (LibraryID),
    CONSTRAINT LIBRARIES_FK1 FOREIGN KEY (BranchOf) REFERENCES LIBRARIES (LibraryID),
    CONSTRAINT LIBRARIES_FK2 FOREIGN KEY (DistrictID) REFERENCES DISTRICTS (DistrictID)
);

CREATE TABLE CITIES (
    LibraryID CHAR(6) NOT NULL,
    City VARCHAR2(100) NOT NULL,
    CONSTRAINT CITIES_PK PRIMARY KEY (LibraryID, City),
    CONSTRAINT CITIES_FK FOREIGN KEY (LibraryID) REFERENCES LIBRARIES (LibraryID)
);

CREATE TABLE GRANTS (
    GrantID CHAR(6) NOT NULL,
    LibraryID CHAR(6) NOT NULL,
    GrantDate DATE NOT NULL,
    Amount NUMBER(*,0) NOT NULL CHECK (Amount>=0),
    Building NUMBER(1,0) NOT NULL CHECK (Building BETWEEN 0 AND 1),
    CONSTRAINT GRANTS_PK PRIMARY KEY (GrantID),
    CONSTRAINT GRANTS_FK FOREIGN KEY (LibraryID) REFERENCES LIBRARIES (LibraryID)
);

